diff --git a/lib/rules/no-unused-expressions.js b/lib/rules/no-unused-expressions.js
index 6529c0a..7547567 100644
--- a/lib/rules/no-unused-expressions.js
+++ b/lib/rules/no-unused-expressions.js
@@ -83,6 +83,66 @@ module.exports = {
 			},
 		] = context.options;

+		/**
+		 * Has AST suggesting a directive.
+		 * @param {ASTNode} node any node
+		 * @returns {boolean} whether the given node structurally represents a directive
+		 */
+		function looksLikeDirective(node) {
+			return (
+				node.type === "ExpressionStatement" &&
+				node.expression.type === "Literal" &&
+				typeof node.expression.value === "string"
+			);
+		}
+
+		/**
+		 * Gets the leading sequence of members in a list that pass the predicate.
+		 * @param {Function} predicate ([a] -> Boolean) the function used to make the determination
+		 * @param {a[]} list the input list
+		 * @returns {a[]} the leading sequence of members in the given list that pass the given predicate
+		 */
+		function takeWhile(predicate, list) {
+			for (let i = 0; i < list.length; ++i) {
+				if (!predicate(list[i])) {
+					return list.slice(0, i);
+				}
+			}
+			return list.slice();
+		}
+
+		/**
+		 * Gets leading directives nodes in a Node body.
+		 * @param {ASTNode} node a Program or BlockStatement node
+		 * @returns {ASTNode[]} the leading sequence of directive nodes in the given node's body
+		 */
+		function directives(node) {
+			return takeWhile(looksLikeDirective, node.body);
+		}
+
+		/**
+		 * Detect if a Node is a directive.
+		 * @param {ASTNode} node any node
+		 * @returns {boolean} whether the given node is considered a directive in its current position
+		 */
+		function isDirective(node) {
+			/**
+			 * https://tc39.es/ecma262/#directive-prologue
+			 *
+			 * Only `FunctionBody`, `ScriptBody` and `ModuleBody` can have directive prologue.
+			 * Class static blocks do not have directive prologue.
+			 *
+			 * The `directive` property alone isn't enough, because parsers don't set it
+			 * when `ecmaVersion` is 3. Conversely, parsers can set it in places this
+			 * structural check doesn't cover, such as TypeScript module blocks.
+			 */
+			return (
+				astUtils.isDirective(node) ||
+				(astUtils.isTopLevelExpressionStatement(node) &&
+					directives(node.parent).includes(node))
+			);
+		}
+
 		/**
 		 * The member functions return `true` if the type has no side-effects.
 		 * Unknown nodes are handled as `false`, then this rule ignores those.
@@ -154,7 +214,7 @@ module.exports = {
 			ExpressionStatement(node) {
 				if (
 					Checker.isDisallowed(node.expression) &&
-					!astUtils.isDirective(node)
+					!isDirective(node)
 				) {
 					context.report({ node, messageId: "unusedExpression" });
 				}
